 192	    @Transactional
 193	    public Order createOrderFromBid(User user, ProductSize productSize, int bidPrice) {
 194	        try {
 195	            // 입력값 검증
 196	            if (user == null) {
 197	                throw new InvalidOrderDataException("사용자 정보가 없습니다.");
 198	            }
 199	            if (productSize == null) {
 200	                throw new ProductSizeNotFoundException("상품 사이즈 정보가 없습니다.");
 201	            }
 202	            if (bidPrice <= 0) {
 203	                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
 204	            }
 205	
 206	            // 1. OrderItem 생성
 207	            OrderItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
 208	
 209	            // 2. Order 생성
 210	            Order order = Order.builder()
 211	                    .user(user)
 212	                    .totalAmount(bidPrice) // 입찰가를 총 금액으로 설정
 213	                    .discountAmount(0) // 초기값은 0
 214	                    .usedPoints(0) // 초기값은 0
 215	                    .status(OrderStatus.PENDING_PAYMENT) // 결제 대기 상태
 216	                    .build();
 217	
 218	            // 3. OrderItem과 연관 설정
 219	            order.addOrderItem(orderItem);
 220	
 221	            // 4. Order 저장
 222	            return orderRepository.save(order);
 223	        } catch (Exception e) {
 224	            if (e instanceof OrderException) {
 225	                throw e;
 226	            }
 227	            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
 228	            throw new OrderCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
 229	        }
 230	    }
